<http://www.example.org/product-review> rdf:type owl:Ontology ;
    rdfs:label "Product Review Ontology" ;
    rdfs:comment "An ontology for representing product reviews and their associated products." .

###  Classes

:Review rdf

@prefix : <http://www.example.org/product-review#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# ---- Product Instances ----

:product1 a :Product ;
    :productName "iPhone 15 Pro" .

:product2 a :Product ;
    :productName "Galaxy S24" .

:product3 a :Product ;
    :productName "iPhone 14" .

:product4 a :Product ;
    :productName "Pixel 8" .

:product5 a :Product ;
    :productName "iPad Air" .

# ---- Review Instances ----

:review1001 a :Review ;
    :reviewId 1001 ;
    :hasProd

bash: cat > query_output.sparql << 'EOF'
PREFIX : <http://www.example.org/product-review#>

SELECT ?reviewId ?reviewTitle ?reviewText ?reviewDate ?productName
WHERE {
  ?review a :Review ;
          :reviewId ?reviewId ;
          :reviewTitle ?reviewTitle ;
          :reviewText ?reviewText ;
          :reviewDate ?reviewDate ;
          :hasProduct ?product .
  ?product :productName ?productName .
  FILTER(CONTAINS(?productName, "iPhone"))
}
EOF
echo "First query written to query_output.sparql"
cat query_output.sparql

